\section{Introduction}

\subsection{Motivation}
Classical factoring methods of the algebraic-group family --- Pollard's $p-1$, Williams'
$p+1$, the elliptic curve method --- share an architecture. One chooses an element $a$ of a
group defined modulo $N$, raises it to a highly composite exponent $M$, and computes a gcd.
Success requires that the order of $a$ modulo one prime factor divide $M$ while the order
modulo another does not. Two independent gambles are involved: the smoothness of the group
order, and the luck of the chosen element. The second is the \emph{bad base problem}.

This paper studies a base-free alternative. Rather than probing with a single residue, we
aggregate over the entire residue system:
\[
F_N(k) = \sum_{a=1}^{N} a^{k}, \qquad g_N(k) = \gcd\bigl(F_N(k), N\bigr).
\]
There is nothing to choose, hence nothing to choose badly. We show that $g_N(k)$ admits an
exact closed form which encodes the factorization of $N$ twice over: in its \emph{values}
(which are literally the prime factors) and in its \emph{period} (the Carmichael function
$\lambda(N)$).

\subsection{Contributions}
\begin{enumerate}
\item A master value table (Theorem~\ref{thm:master}) determining $g_{pq}(k)$ for all $k\ge1$.
\item An unconditional reveal (Corollary~\ref{cor:uncond}) requiring no side condition.
\item A robustness theorem (Theorem~\ref{thm:badbase}) exhibiting a Pollard base bad at
      \emph{every} exponent, and the power sum's success at that exponent.
\item Exact Carmichael periodicity with sharpness (Theorems~\ref{thm:periodic}--\ref{thm:leastperiod}).
\item Correction of a false recovery formula (Theorem~\ref{thm:false}) and its repair
      (Theorem~\ref{thm:repair}), with complete recovery under a guard (Theorem~\ref{thm:recover}).
\item First-hit and density results (Theorems~\ref{thm:firsthit}--\ref{thm:density})
      quantifying the period-finding barrier.
\item Extensions to arbitrary squarefree moduli with a Korselt bridge (Section~\ref{sec:sqfree}),
      and to odd prime powers by a lift-the-exponent recursion (Section~\ref{sec:primepow}).
\end{enumerate}

\subsection{What this is not}
This is not a factoring breakthrough. Section~\ref{sec:complexity} records the honest cost:
$O(N^{3/2})$ to the first hit, strictly worse than trial division's $O(\sqrt N)$. The
interest lies in the completeness of the description and in the light it sheds on why the
encoded information is classically inaccessible.

\section{Definitions}

\begin{definition}[Power sum]
For $N,k\ge 0$ set $F_N(k) = \sum_{a=1}^{N} a^{k}$.
\end{definition}

Note $F_N(0)=N$. For $k\ge1$ and any divisor $d\mid N$, the sums $\sum_{a=1}^{N}a^k$ and
$\sum_{a=0}^{N-1}a^k$ agree modulo $d$, since they differ by $N^k$. We use either freely.

\begin{definition}[Power-sum gcd sequence]
$g_N(k) = \gcd\bigl(F_N(k),\,N\bigr)$.
\end{definition}

\begin{definition}[Carmichael function]
For distinct primes $p,q$, $\lambda(pq) = \lcm(p-1,q-1)$. More generally, for squarefree
$N$, $\lambda(N) = \lcm_{p\mid N}(p-1)$, the exponent of the unit group $(\Zmod{N})^\times$.
\end{definition}

\begin{definition}[Pollard gcd]
$\Pi_N(a,M) = \gcd\bigl(a^{M}-1,\;N\bigr)$. Pollard's $p-1$ method succeeds when
$\Pi_N(a,M)$ is a proper nontrivial divisor of $N$.
\end{definition}

\begin{definition}[Revealing exponent]
An exponent $k\ge1$ is \emph{revealing} for $N$ if $g_N(k)\notin\{1,N\}$.
\end{definition}

\section{The master formula for semiprimes}

\subsection{The Fermat power sum}

\begin{lemma}[Fermat power sum]\label{lem:fermat}
Let $p$ be prime and $k\ge1$. Then in $\Zmod{p}$,
\[
\sum_{x\in\Zmod{p}} x^{k} =
\begin{cases}
-1, & (p-1)\mid k,\\
\phantom{-}0, & \text{otherwise.}
\end{cases}
\]
\end{lemma}

\begin{proof}[Proof sketch]
Since $k\ge1$ the term $x=0$ vanishes, so the sum runs over the cyclic group
$(\Zmod{p})^\times$ of order $p-1$. If $(p-1)\mid k$ then $x^k=1$ for every unit by
Fermat's little theorem, giving $p-1\equiv-1$. Otherwise choose a generator $g$; then
$g^k\ne1$, and $x\mapsto gx$ permutes the units, so $S=\sum_x x^k$ satisfies $g^kS=S$,
whence $(g^k-1)S=0$ and $S=0$ in the field $\Zmod p$.
\end{proof}

\subsection{The periodicity reduction}

\begin{lemma}[Full-period summation]\label{lem:period}
Let $p\ge1$ and $f\colon\Zmod{p}\to\Zmod{p}$. Then
$\sum_{a=0}^{p-1} f(a\bmod p) = \sum_{x\in\Zmod p} f(x)$, and for every $m\ge0$,
$\sum_{a=0}^{pm-1} f(a\bmod p) = m\sum_{x\in\Zmod p} f(x)$.
\end{lemma}

\begin{proof}[Proof sketch]
The first identity is the bijection $a\mapsto a\bmod p$. The second follows by induction on
$m$: split $[0,pm+p)$ into $[0,pm)$ and a shifted copy of $[0,p)$; since $pm\equiv0\pmod p$
the shift is invisible to $f$.
\end{proof}

\begin{proposition}[Reduction of the power sum]\label{prop:reduce}
For $p\ge1$, $m\ge0$, $k\ge1$ and $N=pm$, in $\Zmod p$
\[
F_N(k) \;\equiv\; m\cdot\sum_{x\in\Zmod p} x^{k} \pmod p.
\]
\end{proposition}

\begin{proof}[Proof sketch]
Replace $[1,N]$ by $[0,N)$: the sums differ by $N^k$, which vanishes mod $p$ since
$p\mid N$ and $k\ge1$. Then apply Lemma~\ref{lem:period} with $f(x)=x^k$.
\end{proof}

Intuitively, the interval $[1,pm]$ covers each residue class modulo $p$ exactly $m$ times,
so the power sum mod $p$ is $m$ copies of the residue-system power sum, which
Lemma~\ref{lem:fermat} evaluates.

\subsection{Divisibility and the gcd}

\begin{theorem}[Divisibility criterion]\label{thm:divis}
Let $p$ be prime, $m\ge1$ with $p\nmid m$, and $k\ge1$. Then
\[
p \mid F_{pm}(k) \iff (p-1)\nmid k .
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:reduce} and Lemma~\ref{lem:fermat},
$F_{pm}(k)\equiv m\varepsilon\pmod p$ with $\varepsilon=-1$ if $(p-1)\mid k$ and
$\varepsilon=0$ otherwise. As $m\not\equiv0$, we get $m\varepsilon\equiv0$ iff
$\varepsilon=0$.
\end{proof}

\begin{theorem}[Master formula]\label{thm:master}
Let $N=pq$ with $p\ne q$ prime and $k\ge1$. Then
\[
g_N(k)=\gcd\bigl(F_N(k),N\bigr)
= \Bigl((p-1)\mid k\;?\;1:p\Bigr)\cdot\Bigl((q-1)\mid k\;?\;1:q\Bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$p$ and $q$ are coprime, so $\gcd(x,pq)=\gcd(x,p)\gcd(x,q)$; and for a prime $r$,
$\gcd(x,r)=r$ if $r\mid x$, else $1$. Apply Theorem~\ref{thm:divis} twice, with $m=q$
(valid since $p\nmid q$) and with $m=p$.
\end{proof}

\begin{center}
\begin{tabular}{ccll}
\toprule
$(p-1)\mid k$ & $(q-1)\mid k$ & $g_N(k)$ & interpretation \\
\midrule
no  & no  & $N$ & trivial: sum divisible by $N$ \\
yes & no  & $q$ & \textbf{factor revealed} \\
no  & yes & $p$ & \textbf{factor revealed} \\
yes & yes & $1$ & trivial: sum coprime to $N$ \\
\bottomrule
\end{tabular}
\end{center}

\begin{corollary}[Factor reveal]\label{cor:reveal}
If $p\ne q$ are prime and $(q-1)\nmid(p-1)$, then
$\gcd\bigl(\sum_{a=1}^{pq} a^{\,p-1},\,pq\bigr)=q$. Dually, if $(p-1)\nmid(q-1)$ then
$g_{pq}(q-1)=p$.
\end{corollary}

\begin{corollary}[Properness]
Under the hypotheses of Corollary~\ref{cor:reveal}, $q$ is a proper nontrivial divisor of
$N$: indeed $q\ne1$ and $q\ne pq$ since $p>1$.
\end{corollary}

\section{Robustness: no bad base}

\begin{lemma}\label{lem:pollardcast}
Let $r$ be a prime with $r\mid N$ and $N\ge2$. Then in $\Zmod r$,
$(N-1)^M-1 \equiv (-1)^M-1$.
\end{lemma}

\begin{lemma}\label{lem:pollardparity}
Let $r$ be an odd prime dividing $N\ge2$. If $M$ is odd then $r\nmid (N-1)^M-1$ (the
quantity is $\equiv -2\not\equiv0$); if $M$ is even then $r\mid (N-1)^M-1$.
\end{lemma}

\begin{theorem}[A universally bad Pollard base]\label{thm:badbase}
Let $N=pq$ with $p\ne q$ distinct \emph{odd} primes. Then for every exponent $M\ge0$,
\[
\Pi_N(N-1,M)=\gcd\bigl((N-1)^M-1,\;N\bigr)=
\begin{cases} N, & M \text{ even},\\ 1, & M \text{ odd}.\end{cases}
\]
In particular it is never a proper divisor of $N$, for any exponent whatsoever.
\end{theorem}

\begin{proof}[Proof sketch]
Split the gcd across the coprime factors $p,q$ and apply Lemma~\ref{lem:pollardparity} to
each, according to the parity of $M$.
\end{proof}

\begin{proposition}[The bad base is legitimate]
For distinct odd primes $p,q$ and $N=pq$, the base $a=N-1$ satisfies $1<a<N$ and
$\gcd(a,N)=1$.
\end{proposition}

\begin{theorem}[Robustness]\label{thm:robust}
Let $p\ne q$ be distinct odd primes with $(q-1)\nmid(p-1)$, and $N=pq$. At the exponent
$k=p-1$ (which is even),
\[
\Pi_N(N-1,\,p-1)=N \quad\text{(Pollard fails)},\qquad
g_N(p-1)=q \quad\text{(power sum succeeds)}.
\]
\end{theorem}

\begin{example}
$N=35=5\cdot7$, $M=4=p-1$, base $a=6=N-1$. Then $6^4-1=1295=35\cdot37$, so
$\gcd(1295,35)=35$: Pollard returns the whole modulus. At the same exponent
$\gcd(F_{35}(4),35)=7$.
\end{example}

The conceptual content: a base-dependent method can fail \emph{totally and permanently} for
a legitimate base, while the base-free aggregate does not share that failure mode, because
it averages over all residues at once and Fermat's theorem evaluates the average exactly.

\section{First hit and density of revealing exponents}

\begin{proposition}\label{prop:eqN}
For $N=pq$ with $p\ne q$ prime and $k\ge1$:
$g_N(k)=N \iff \bigl((p-1)\nmid k \text{ and } (q-1)\nmid k\bigr)$.
\end{proposition}

\begin{lemma}\label{lem:autoside}
If $p<q$ are primes then $(q-1)\nmid(p-1)$.
\end{lemma}

\begin{proof}
$p-1\ge1>0$, and any positive multiple of $q-1$ is at least $q-1>p-1$.
\end{proof}

\begin{corollary}[Unconditional factor reveal]\label{cor:uncond}
For distinct primes $p<q$, $g_{pq}(p-1)=q$, with no divisibility side condition.
\end{corollary}

\begin{theorem}[First hit]\label{thm:firsthit}
Let $N=pq$, $p\ne q$ prime. Then $k^\ast=\min(p-1,q-1)$ is the least positive exponent with
$g_N(k)\ne N$.
\end{theorem}

\begin{proof}[Proof sketch]
At $k=k^\ast$ one of $p-1,q-1$ equals $k^\ast$, so by Proposition~\ref{prop:eqN}
$g_N(k^\ast)\ne N$. Conversely if $g_N(k)\ne N$ with $k\ge1$ then $(p-1)\mid k$ or
$(q-1)\mid k$; either divisor is $\le k$, so $k^\ast\le k$.
\end{proof}

\begin{theorem}
If $p<q$ then $g_N(k^\ast)=g_N(p-1)=q$: the first hit is already a proper factor.
\end{theorem}

\begin{theorem}[First hit below the square root]\label{thm:sqrt}
For primes $p,q$, $\bigl(\min(p-1,q-1)+1\bigr)^2\le pq$, i.e.\ $k^\ast<\sqrt N$.
\end{theorem}

\begin{lemma}\label{lem:inter}
Inside $(0,\lambda]$ with $\lambda=\lambda(N)$, the multiples of $p-1$ and the multiples of
$q-1$ intersect exactly in $\{\lambda\}$.
\end{lemma}

\begin{theorem}[Density inside one period]\label{thm:density}
Let $N=pq$ with $p\ne q$ prime and $\lambda=\lambda(N)$. The number of revealing exponents
in $(0,\lambda]$ is exactly
\[
\frac{\lambda}{p-1}+\frac{\lambda}{q-1}-2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:master}, $k$ is revealing iff exactly one of $(p-1)\mid k$,
$(q-1)\mid k$ holds. With $A,B$ the sets of multiples of $p-1$, $q-1$ in $(0,\lambda]$, the
revealing set is the disjoint union $(A\setminus B)\cup(B\setminus A)$, of cardinality
$|A|+|B|-2|A\cap B|$. Now $|A|=\lambda/(p-1)$, $|B|=\lambda/(q-1)$, and $|A\cap B|=1$ by
Lemma~\ref{lem:inter}.
\end{proof}

\begin{example}
$N=35$: $\lambda=12$ and $12/4+12/6-2=3$; the revealing exponents in $\{1,\dots,12\}$ are
$k=4,6,8$ with values $7,5,7$.
\end{example}

The proportion of revealing exponents per period is $\tfrac1{p-1}+\tfrac1{q-1}-\tfrac2\lambda$,
negligible at cryptographic sizes. This is the quantitative form of the period-finding
barrier.

\section{Carmichael periodicity}

\begin{theorem}[Periodicity]\label{thm:periodic}
Let $N=pq$, $p\ne q$ prime, $k\ge1$. Then $g_N\bigl(k+\lambda(N)\bigr)=g_N(k)$.
\end{theorem}

\begin{proof}[Proof sketch]
$(p-1)\mid\lambda(N)$, so $(p-1)\mid(k+\lambda(N))\iff(p-1)\mid k$; similarly for $q-1$.
The master formula depends on $k$ only through these two predicates.
\end{proof}

\begin{theorem}[Trivial values are the multiples of $\lambda$]\label{thm:one}
For $k\ge1$, $g_N(k)=1 \iff \lambda(N)\mid k$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $p,q>1$, the product in Theorem~\ref{thm:master} equals $1$ only if both brackets are
$1$, i.e.\ $(p-1)\mid k$ and $(q-1)\mid k$, i.e.\ $\lcm(p-1,q-1)\mid k$; the converse is
immediate.
\end{proof}

\begin{theorem}[$\lambda(N)$ is legible]\label{thm:legible}
$\lambda(N)$ is the least element of $\{k\ge1: g_N(k)=1\}$.
\end{theorem}

\begin{theorem}[Exact minimality of the period]\label{thm:leastperiod}
For every $d$ with $0<d<\lambda(N)$ there is $k\ge1$ with $g_N(k+d)\ne g_N(k)$. Hence
$\lambda(N)$ is the least period of $g_N$ on $k\ge1$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $k=\lambda(N)$, so $g_N(k)=1$. If $\lambda(N)\mid \lambda(N)+d$ then $\lambda(N)\mid d$
and $\lambda(N)\le d$, contradicting $d<\lambda(N)$. So $g_N(\lambda(N)+d)\ne1$.
\end{proof}

